import { useState, useEffect } from "react";

function PostList({ selectedPost, onSelectPost, reload, categoryId }) {
    const [posts, setPosts] = useState([]);

    useEffect(() => {
        const fetchPosts = async () => {
            try {
                let url = "http://localhost:5000/api/posts";
                if (categoryId) url += `?category=${categoryId}`;

                const res = await fetch(url);
                const data = await res.json();
                setPosts(data);
            } catch (err) {
                console.error("Помилка при завантаженні постів:", err);
                setPosts([]);
            }
        };

        fetchPosts();
    }, [reload, categoryId]);

    return (
        <div className="space-y-4">
            <h3 className="text-2xl font-bold gradient-text mb-4">
                Список постів ({posts.length})
            </h3>

            {posts.length === 0 ? (
                <div className="card-gradient rounded-2xl p-12 text-center">
                    <p className="text-gray-500 font-medium">Пости відсутні</p>
                </div>
            ) : (
                <ul className="space-y-3">
                    {posts.map((post) => (
                        <li
                            key={post.id}
                            onClick={() => onSelectPost(post.id)}
                            className={`card-gradient rounded-xl p-6 cursor-pointer transition-all duration-300 transform ${post.id === selectedPost
                                ? "ring-4 ring-primary-400 shadow-xl shadow-primary-500/30"
                                : "hover:shadow-xl"
                                }`}
                        >
                            <h4 className="text-xl font-bold mb-2">{post.title}</h4>
                            <p className="text-gray-600 line-clamp-2">{post.content}</p>
                            <div className="flex justify-between mt-4 text-sm text-gray-500">
                                <span>{post.username || "Користувач"}</span>
                                <span>{new Date(post.created_at).toLocaleDateString("uk-UA")}</span>
                            </div>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
}

export default PostList;
